{
  "headline": "Hydrochlorothiazide is not on FDA's shortage list; Corvale sites have 19-20 days on hand and the rule recommends buying from Accord Healthcare Inc.",
  "headline_cites": ["D3", "D1", "D2", "D4"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include hydrochlorothiazide as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East holds 231 tablets of the 25 mg presentation at 11.6 tablets per day, giving 19.9 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 262 tablets of the 25 mg presentation at 13.8 tablets per day, giving 19 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "The label for NDC 51655027226 names Northwind Health Company, LLC as the labeler and plant (FEI 1831143) with a VAI inspection on 2025-09-26.",
      "cites": ["E9"]
    },
    {
      "text": "That plant, Northwind Pharmaceuticals LLC, received an OAI classification on 2015-12-09 and VAI classifications on 2015-09-14, 2018-11-16, and 2025-09-26.",
      "cites": ["E4", "E6", "E7", "E8"]
    },
    {
      "text": "The rule's top option is to buy from Accord Healthcare Inc., which is not on FDA's shortage list today and whose label names no plant we could place.",
      "cites": ["D4"]
    },
    {
      "text": "Secondary options are Actavis Pharma, Inc. and Aurobindo Pharma Limited, also not on the shortage list and with no placeable plant on their labels.",
      "cites": ["D5", "D6"]
    }
  ]
}
